import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.CZqXuAiL.js";const c=JSON.parse('{"title":"Recipes","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/user-guide/recipes.md","filePath":"openshield-xdp/user-guide/recipes.md","lastUpdated":null}'),n={name:"openshield-xdp/user-guide/recipes.md"};function l(p,s,h,r,o,k){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h1><p>Starting points for common server types. Each assumes you ran the installer and picked the suggested preset. Apply edits to <code>/etc/openshield/openshield.yaml</code>, then <code>sudo openshield reload</code>.</p><h2 id="game-server-minecraft-fivem-rust-cs2" tabindex="-1">Game server (Minecraft, FiveM, Rust, CS2) <a class="header-anchor" href="#game-server-minecraft-fivem-rust-cs2" aria-label="Permalink to &quot;Game server (Minecraft, FiveM, Rust, CS2)&quot;">​</a></h2><p><strong>Preset:</strong> Gaming.</p><p>Gaming traffic is bursty UDP from many players — the preset already tolerates that. Two additions worth making:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  port_thresholds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;25565&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # your game port</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      pps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # a full server can legitimately push thousands of pps</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      bps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # inherit global</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dynamic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  attack_port_pps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # per-port cap during attacks (Gaming preset default)</span></span></code></pre></div><ul><li><code>attack_port_pps</code> is your real flood defense: a flood aimed at your game port is capped at the port level regardless of how many spoofed IPs it rotates through. Keep it comfortably above your busiest full-server night.</li><li>Don&#39;t raise global <code>udp_pps_threshold</code> for players&#39; sake — per-IP limits should stay tight; legit players never come close.</li></ul><h2 id="hosting-node-pterodactyl-docker-vps-node" tabindex="-1">Hosting node (Pterodactyl, Docker, VPS node) <a class="header-anchor" href="#hosting-node-pterodactyl-docker-vps-node" aria-label="Permalink to &quot;Hosting node (Pterodactyl, Docker, VPS node)&quot;">​</a></h2><p><strong>Preset:</strong> Hosting.</p><p>Many customer services share one interface, and customer traffic spikes are usually legitimate. The preset focuses on attack patterns over raw rates.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dynamic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  attack_min_pps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # a busy node shouldn&#39;t trip attack mode on normal load</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  attack_port_pps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # Hosting preset default</span></span></code></pre></div><ul><li>Whitelist your panel/monitoring IPs: <code>sudo openshield wl add 203.0.113.10</code> (persists to the config).</li><li>If one customer port (e.g. a popular game server) keeps tripping per-port caps, give it a <code>port_thresholds</code> entry rather than loosening the whole node.</li></ul><h2 id="file-backup-server-sftp-rsync-s3-gateway-storage-node" tabindex="-1">File / backup server (SFTP, rsync, S3 gateway, storage node) <a class="header-anchor" href="#file-backup-server-sftp-rsync-s3-gateway-storage-node" aria-label="Permalink to &quot;File / backup server (SFTP, rsync, S3 gateway, storage node)&quot;">​</a></h2><p><strong>Preset:</strong> Database (designed for DBs, file storage, backups, mail).</p><p>Bulk transfers are exactly what v2.0&#39;s established-connection exemption was built for: once a client completes a real TCP session, it&#39;s exempt from PPS/BPS/TCP scoring, so a 40 GB upload won&#39;t get banned. Make sure it&#39;s on:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ct_established_exempt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # default — the &quot;stop banning my backups&quot; switch</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ct_syn_timeout_sec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # keep ≥ your app&#39;s keepalive interval</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  port_thresholds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># optional, for pure-UDP transfer tools (no TCP session)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;5001&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      pps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20000</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      bps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">104857600</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 100 MB/s</span></span></code></pre></div><p>If you still see transfer bans, check that the traffic is really TCP — UDP-based transfer tools never establish a session, so they need a port override (above) or a whitelist entry for the backup peer.</p><h2 id="vpn-server-wireguard-openvpn" tabindex="-1">VPN server (WireGuard, OpenVPN) <a class="header-anchor" href="#vpn-server-wireguard-openvpn" aria-label="Permalink to &quot;VPN server (WireGuard, OpenVPN)&quot;">​</a></h2><p><strong>Preset:</strong> Performance or Balanced.</p><p>A VPN concentrates all your clients&#39; traffic into tunnel packets from a handful of endpoints — legitimate per-endpoint rates are far above normal.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  port_thresholds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;51820&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # WireGuard</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      pps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50000</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      bps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # inherit global BPS, or set your line rate</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dynamic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  conn_rate_limit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # fine as-is; VPNs don&#39;t open many TCP conns</span></span></code></pre></div><ul><li>Whitelist nothing except management IPs — the tunnel port gets its allowance from <code>port_thresholds</code>, not from blanket exemptions.</li><li>UDP floods aimed at the VPN port during an attack are handled by <code>attack_port_pps</code>; legit tunnel traffic on the port is throttled, not banned, until the attack clears.</li></ul><h2 id="minecraft-network-proxy-velocity-bungee-→-paper-backend" tabindex="-1">Minecraft network: proxy (Velocity/Bungee) → Paper backend <a class="header-anchor" href="#minecraft-network-proxy-velocity-bungee-→-paper-backend" aria-label="Permalink to &quot;Minecraft network: proxy (Velocity/Bungee) → Paper backend&quot;">​</a></h2><p><strong>The one thing to understand:</strong> when a proxy fronts your Paper server, <em>every</em> player&#39;s traffic arrives at the Paper host <strong>from the proxy&#39;s IP</strong>. Per-IP limits on the backend see one super-source carrying hundreds of players.</p><p><strong>Best topology:</strong> run OpenShield on the <strong>proxy&#39;s public interface</strong> — that&#39;s where real player IPs are visible and where floods actually arrive. The proxy preset (Gaming) applies as usual.</p><p>If you <em>also</em> run OpenShield on the Paper backend host (different machine), tell it the proxy is trusted infrastructure:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  port_thresholds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;25565&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # backend listener the proxy forwards to</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      pps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # one IP = all your players</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      bps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">proxy-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # never rate-limit or ban the proxy</span></span></code></pre></div><ul><li>Whitelisting the proxy IP is safe: the proxy&#39;s own OpenShield (or its firewall) is the layer that judges real players. If an attacker floods the <em>backend directly</em>, they must know its IP — keep the backend firewalled to proxy-only at the network level too (UFW/security group), OpenShield is not a substitute for that.</li><li><strong>Do not</strong> whitelist the proxy on the <em>proxy&#39;s own</em> host — there it&#39;s just another local process, and player IPs are what you want judged.</li><li>Same pattern applies to any TCP/UDP reverse proxy: HAProxy → backends, nginx → app servers, game relays.</li></ul><h2 id="any-recipe-verify-before-and-after" tabindex="-1">Any recipe: verify before and after <a class="header-anchor" href="#any-recipe-verify-before-and-after" aria-label="Permalink to &quot;Any recipe: verify before and after&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # loaded? which features active?</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stats</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # TUI: watch normal traffic for a day</span></span></code></pre></div><p>Watch the TUI during your busiest hour before tuning. If normal traffic sits at 30% of a threshold, the threshold is fine — don&#39;t tune against quiet-hour numbers.</p>`,32)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
